insert into service_categories (slug, name, description, icon) values
('home','Home services','Repairs and help around the home','⌂'),('mechanical','Mechanical','Vehicles, tyres and roadside help','⚙'),('construction','Builders & construction','Masonry, welding and civil work','▦'),('interior','Interior & improvement','Make your space feel like yours','✦') on conflict (slug) do nothing;
insert into services (category_id, slug, name, keywords) select c.id, x.slug, x.name, x.keywords from service_categories c cross join (values ('home','ac-repair','AC repair',array['ac','cooling']),('home','plumber','Plumber',array['pipe','leak','water']),('home','electrician','Electrician',array['power','wiring']),('mechanical','bike-repair','Bike repair',array['bike','motorcycle']),('mechanical','tyre-help','Tyre & roadside help',array['tyre','puncture']),('construction','mason','Mason',array['wall','brick']),('construction','painter','Painting',array['paint','wall']),('construction','welder','Welding',array['weld','metal']),('interior','interior-designer','Interior design',array['interior','renovation']),('interior','carpenter','Carpenter',array['wood','furniture'])) as x(category_slug,slug,name,keywords) where c.slug=x.category_slug on conflict (slug) do nothing;
